<?php\n\n// require_once é melhor que include para classes\n// pois se o arquivo já foi incluído, não tenta incluir de novo\n// e gera erro se não existir\n\nrequire_once 'Usuario.php';\n\nsession_start();\n\necho \"=== Sistema de Login ===\\n\\n\";\n\n// Criar e autenticar usuário\n\$usuario = new Usuario(\"João Silva\");\n\$usuario->autenticar();\n\necho \"Usuário: \" . \$usuario->getNome() . \"\\n\";\necho \"Logado: \" . (\$usuario->estaLogado() ? \"Sim\" : \"Não\") . \"\\n\";\n\n// Armazenar na sessão\n\$_SESSION['nomeUsuario'] = \$usuario->getNome();\n\$_SESSION['logado'] = \$usuario->estaLogado();\n\$_SESSION['horaLogin'] = date('H:i:s');\n\necho \"\\nDados salvos na sessão:\\n\";\necho \"- nomeUsuario: \" . \$_SESSION['nomeUsuario'] . \"\\n\";\necho \"- logado: \" . (\$_SESSION['logado'] ? \"true\" : \"false\") . \"\\n\";\necho \"- horaLogin: \" . \$_SESSION['horaLogin'] . \"\\n\";\n\n// Cookie com data de acesso\necho \"\\nCookie lastAccess seria criado com data: \" . date('d/m/Y H:i:s') . \"\\n\";\n\necho \"\\n--- Sessão vs Cookie ---\\n\";\necho \"Sessão: dados no servidor, mais seguro\\n\";\necho \"Cookie: dados no cliente, visível mas prático para preferências\\n\";\n\n?>"
